INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(118209, 'ruRU', '', 'Чтобы заставить врага прекратить бой на короткое время, воспользуйся самим страхом, чтобы вселить ужас в его сердце.', 24330),
(118210, 'ruRU', '', 'Иногда ты можешь оказаться в затруднении из-за нескольких врагов или одного врага, слишком сильного для тебя.', 24330),
(118211, 'ruRU', '', 'Используй Жертвование жизнью, чтобы восполнить запасы маны.', 24330),
(118212, 'ruRU', '', 'Жертвование жизнью позволяет забрать собственную жизненную силу, чтобы восполнить ману. Не волнуйся, ты всегда можешь вытянуть жизнь у противника, чтобы исцелиться.', 24330),
(118213, 'ruRU', '', 'Многие заклинания требуют большого запаса маны. Но у тебя есть хитрый способ решить эту проблему.', 24330),
(118214, 'ruRU', '', 'Используй Призыв прислужника Пустоты, чтобы призвать своего демонического слугу.', 24330),
(118215, 'ruRU', '', 'Твоё владение тёмной магией позволяет призывать демона-слугу, чтобы исполнять твои приказы.', 24330),
(118216, 'ruRU', '', 'Чернокнижники немощи используют магию тьмы и болезни, чтобы изматывать врагов, а затем вытягивают саму сущность их жизни, чтобы усилить себя.', 24330),
(118217, 'ruRU', '', 'У тебя максимум Осколков души. Используй Нестабильную немощь!', 24330),
(118218, 'ruRU', '', 'Используй Нестабильную немощь!', 24330),
(118219, 'ruRU', '', 'Нестабильная немощь доступна! Используй её сейчас!', 24330),
(118220, 'ruRU', '', 'Твой прислужник Пустоты погиб. Используй Призыв прислужника Пустоты, чтобы вернуть его.', 24330),
(118221, 'ruRU', '', 'Используй Жертвование жизнью, чтобы восполнить ману!', 24330),
(118222, 'ruRU', '', 'У тебя мало здоровья, используй свой Камень здоровья!', 24330),
(118223, 'ruRU', '', 'Используй Страх!', 24330),
(118224, 'ruRU', '', 'Используй Похищение жизни!', 24330),
(118225, 'ruRU', '', 'Используй Похищение жизни на своей цели!', 24330),
(118226, 'ruRU', '', 'Призови своего стража гибели прямо сейчас!', 24330),
(118227, 'ruRU', '', 'Используй Порчу!', 24330),
(118228, 'ruRU', '', 'Порча истекла! Используй её снова!', 24330),
(118229, 'ruRU', '', 'Повторно наложи Агонию прямо перед её истечением, чтобы сохранить её усиленный урон!', 24330),
(118230, 'ruRU', '', 'Используй Агонию!', 24330),
(118231, 'ruRU', '', 'Агония истекла! Используй её снова!', 24330),
(118232, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как чернокнижник немощи.', 24330),
(118233, 'ruRU', '', 'Но, прошу, не наноси им слишком сильный урон. Они мне ещё понадобятся.', 24330),
(118234, 'ruRU', '', 'Хотя Нестабильная немощь наносит урон со временем, каждое повторное наложение увеличивает её силу. Используй эту атаку, когда можешь!', 24330),
(118235, 'ruRU', '', 'Используй Нестабильную немощь на этом тренировочном манекене.', 24330),
(118236, 'ruRU', '', 'Нестабильная немощь — мощное заклинание, наносящее урон со временем, как Агония и Порча, но использующее Осколок души, чтобы наносить больше урона.', 24330),
(118237, 'ruRU', '', 'Пока Агония наносит урон врагу, у неё есть шанс создать Осколок души. Ты можешь использовать эти осколки, чтобы усилить новые способности.', 24330),
(118238, 'ruRU', '', 'Используй Похищение души на тренировочном манекене.', 24330),
(118239, 'ruRU', '', 'Похищение души — атака, которую ты будешь использовать чаще всего, исцеляя тебя, пока наносит урон врагу.', 24330),
(118240, 'ruRU', '', 'После наложения на цель Агонии и Порчи ты можешь начать вытягивать саму жизнь из неё.', 24330),
(118241, 'ruRU', '', 'Как только ты применишь Порчу, тебе не нужно применять её снова, пока первоначальное заклинание не близится к истечению.', 24330),
(118242, 'ruRU', '', 'Используй Порчу на этом тренировочном манекене.', 24330),
(118243, 'ruRU', '', 'Порча — заклинание, поражающее цель, наносящее урон тьмой, пока длится воздействие.', 24330),
(118244, 'ruRU', '', 'Ты принесёшь страдания любому, кто окажется настолько глуп, чтобы сражаться с тобой.', 24330),
(118245, 'ruRU', '', 'Как только ты применишь Агонию, тебе не нужно применять её снова, пока первоначальное заклинание не близится к истечению.', 24330),
(118246, 'ruRU', '', 'Используй Агонию на тренировочном манекене.', 24330),
(118247, 'ruRU', '', 'Агония наносит всё больше урона со временем, что делает её отличным способом начать бой.', 24330),
(118248, 'ruRU', '', 'Агония — подходящее название для твоей первой атакующей способности.', 24330);
